System.register([],function(n,t){"use strict";return{execute:function(){n("default",'# 📘 第14课：综合训练\n\n> **课程定位**：函数 + 高精度 + 排序 综合应用\n\n---\n\n## 一、学习目标\n\n1. ✅ 综合运用前面所学知识\n2. ✅ 学会拆解复杂问题\n3. ✅ 强化代码结构设计\n4. ✅ 模拟 CSP-J 难度\n\n---\n\n## 二、综合题设计原则\n\n### 2.1 函数封装思想\n\n```cpp\nint main() {\n    // 主函数只做调度\n    readInput();\n    process();\n    printOutput();\n    return 0;\n}\n```\n\n### 2.2 代码结构\n\n```\n1. 全局变量/常量定义\n2. 工具函数（如 swap, max, min）\n3. 核心算法函数\n4. 输入输出函数\n5. main 函数\n```\n\n---\n\n## 三、综合题一：高精度阶乘\n\n**题目**：计算 n! 的精确值。\n\n```cpp\n#include <iostream>\n#include <string>\nusing namespace std;\n\nstring multiply(string num, int x) {\n    if (x == 0) return "0";\n    string result = "";\n    int carry = 0;\n    for (int i = num.length() - 1; i >= 0 || carry; i--) {\n        int product = carry;\n        if (i >= 0) product += (num[i] - \'0\') * x;\n        result = (char)(product % 10 + \'0\') + result;\n        carry = product / 10;\n    }\n    return result;\n}\n\nstring factorial(int n) {\n    string result = "1";\n    for (int i = 2; i <= n; i++) {\n        result = multiply(result, i);\n    }\n    return result;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    cout << factorial(n) << endl;\n    return 0;\n}\n```\n\n---\n\n## 四、综合题二：排名系统\n\n**题目**：输入 n 个学生的成绩，按成绩排序后输出排名。成绩相同的学生排名相同。\n\n```cpp\n#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nstruct Student {\n    string name;\n    int score;\n    int rank;\n};\n\nbool cmp(Student a, Student b) {\n    return a.score > b.score;\n}\n\nint main() {\n    int n;\n    cin >> n;\n\n    Student students[110];\n    for (int i = 0; i < n; i++) {\n        cin >> students[i].name >> students[i].score;\n    }\n\n    sort(students, students + n, cmp);\n\n    // 计算排名\n    students[0].rank = 1;\n    for (int i = 1; i < n; i++) {\n        if (students[i].score == students[i-1].score) {\n            students[i].rank = students[i-1].rank;\n        } else {\n            students[i].rank = i + 1;\n        }\n    }\n\n    // 输出\n    for (int i = 0; i < n; i++) {\n        cout << students[i].rank << " "\n             << students[i].name << " "\n             << students[i].score << endl;\n    }\n\n    return 0;\n}\n```\n\n---\n\n## 五、综合题三：大数加减\n\n**题目**：实现一个计算器，支持两个大整数的加法和减法。\n\n```cpp\n#include <iostream>\n#include <string>\nusing namespace std;\n\n// 比较大小\nint compare(string a, string b) {\n    if (a.length() != b.length())\n        return a.length() > b.length() ? 1 : -1;\n    return a.compare(b);\n}\n\n// 高精度加法\nstring add(string a, string b) {\n    string c = "";\n    int carry = 0;\n    int i = a.length() - 1, j = b.length() - 1;\n    while (i >= 0 || j >= 0 || carry) {\n        int sum = carry;\n        if (i >= 0) sum += a[i--] - \'0\';\n        if (j >= 0) sum += b[j--] - \'0\';\n        c = (char)(sum % 10 + \'0\') + c;\n        carry = sum / 10;\n    }\n    return c;\n}\n\n// 高精度减法（保证 a >= b）\nstring subtract(string a, string b) {\n    string c = "";\n    int borrow = 0;\n    int i = a.length() - 1, j = b.length() - 1;\n    while (i >= 0) {\n        int diff = (a[i--] - \'0\') - borrow;\n        if (j >= 0) diff -= (b[j--] - \'0\');\n        if (diff < 0) { diff += 10; borrow = 1; }\n        else { borrow = 0; }\n        c = (char)(diff + \'0\') + c;\n    }\n    // 去前导零\n    int start = 0;\n    while (start < c.length() - 1 && c[start] == \'0\') start++;\n    return c.substr(start);\n}\n\nint main() {\n    string a, op, b;\n    cin >> a >> op >> b;\n\n    if (op == "+") {\n        cout << add(a, b) << endl;\n    } else {\n        int cmp = compare(a, b);\n        if (cmp == 0) cout << "0" << endl;\n        else if (cmp > 0) cout << subtract(a, b) << endl;\n        else cout << "-" << subtract(b, a) << endl;\n    }\n\n    return 0;\n}\n```\n\n---\n\n## 六、综合题四：区间操作\n\n**题目**：给定 n 个区间，找出所有区间的并集长度。\n\n```cpp\n#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nstruct Interval {\n    int start, end;\n};\n\nbool cmp(Interval a, Interval b) {\n    return a.start < b.start;\n}\n\nint main() {\n    int n;\n    cin >> n;\n\n    Interval intervals[110];\n    for (int i = 0; i < n; i++) {\n        cin >> intervals[i].start >> intervals[i].end;\n    }\n\n    sort(intervals, intervals + n, cmp);\n\n    int totalLength = 0;\n    int curStart = intervals[0].start;\n    int curEnd = intervals[0].end;\n\n    for (int i = 1; i < n; i++) {\n        if (intervals[i].start <= curEnd) {\n            curEnd = max(curEnd, intervals[i].end);\n        } else {\n            totalLength += curEnd - curStart;\n            curStart = intervals[i].start;\n            curEnd = intervals[i].end;\n        }\n    }\n    totalLength += curEnd - curStart;\n\n    cout << totalLength << endl;\n    return 0;\n}\n```\n\n---\n\n## 七、解题技巧总结\n\n### 7.1 审题要点\n\n- 数据范围（决定算法复杂度）\n- 边界条件（空输入、极值）\n- 输出格式（换行、空格）\n\n### 7.2 代码习惯\n\n- 先写框架，再填细节\n- 函数功能单一\n- 多写注释\n- 边界测试\n\n### 7.3 调试方法\n\n- 手算小例子\n- 打印中间结果\n- 边界值测试\n\n---\n\n## 八、热身练习\n\n### 练习 1：简单计算器\n\n**题目**：读入一个算式（如 `1+2` 或 `5*3`），输出结果。保证操作数是整数，运算符只有 `+`、`-`、`*`、`/`。\n\n### 练习 2：质数判断\n\n**题目**：写一个函数 `bool isPrime(int n)`，判断 n 是否为质数。如果是输出 "Yes"，否则输出 "No"。\n\n---\n\n## 九、本课小结\n\n综合训练的关键：\n\n1. ✅ 函数封装，结构清晰\n2. ✅ 灵活组合基础算法\n3. ✅ 注意边界情况\n4. ✅ 代码可读性\n\n---\n\n**下节预告**：第15课 - 终极测评！\n')}}});
